// n8n Code Node: Clean & Parse Student Records

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

return $input.all().map((item, index) => {
  let raw = item.json;

  // 1. If the AI output is a string (or inside a common field like `text`, `output`, or `response`), parse it
  if (typeof raw === 'string') {
    raw = parseJsonSafely(raw);
  } else if (typeof raw.text === 'string') {
    raw = parseJsonSafely(raw.text);
  } else if (typeof raw.output === 'string') {
    raw = parseJsonSafely(raw.output);
  } else if (typeof raw.response === 'string') {
    raw = parseJsonSafely(raw.response);
  }

  const record = raw && typeof raw === 'object' ? raw : {};

  // 2. Clean & validate individual fields
  const studentId = cleanString(record.Student_ID);
  const name = cleanString(record.Name);

  const rawEmail = cleanString(record.Email);
  const isValidEmail = Boolean(rawEmail && emailRegex.test(rawEmail));
  const email = isValidEmail ? rawEmail.toLowerCase() : null;

  const rawPhone = cleanString(record.Phone);
  const cleanedPhone = rawPhone ? rawPhone.replace(/\D/g, '') : null;

  const course = cleanString(record.Course);
  const city = cleanString(record.City);
  const feePaid = parseBoolean(record.Fee_Paid);
  const enrolledDate = parseDate(record.Enrolled_Date);

  return {
    json: {
      student_id: studentId,
      name: name,
      email: email,
      email_status: isValidEmail ? 'valid' : 'invalid_or_missing',
      phone: cleanedPhone,
      course: course,
      fee_paid: feePaid,
      city: city,
      enrolled_date: enrolledDate,
      _row_index: index + 1,
    },
  };
});

// --- Helper Functions ---

function parseJsonSafely(str) {
  try {
    // Remove ```json ... ``` or ``` ... ``` wrappers if present
    const cleaned = str
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();
    return JSON.parse(cleaned);
  } catch (err) {
    return { _parse_error: err.message, _raw: str };
  }
}

function cleanString(val) {
  if (val === null || val === undefined) return null;
  const trimmed = String(val).trim();
  return trimmed.length > 0 ? trimmed : null;
}

function parseBoolean(val) {
  if (typeof val === 'boolean') return val;
  if (typeof val === 'string') {
    const lower = val.trim().toLowerCase();
    if (lower === 'true' || lower === 'yes' || lower === '1') return true;
    if (lower === 'false' || lower === 'no' || lower === '0') return false;
  }
  return false;
}

function parseDate(val) {
  if (!val) return null;
  const d = new Date(val);
  return Number.isNaN(d.getTime()) ? null : d.toISOString().split('T')[0]; // YYYY-MM-DD
}
